    // A zero budget is invalid by contract; treating it as one attempt keeps
    // the runner from silently skipping the job when supplied bad config.
    let max_attempts = config.max_attempts.max(1);
    let mut attempt = 0;

    loop {
        attempt += 1;
        match job() {
            Ok(()) => return Ok(()),
            Err(error) if error.is_transient() && attempt < max_attempts => {
                let exponent = attempt - 1;
                let delay = config
                    .base_delay_ms
                    .checked_mul(2u64.saturating_pow(exponent))
                    .unwrap_or(u64::MAX)
                    .min(config.max_delay_ms);
                sleeper.sleep_ms(delay);
            }
            Err(error) => return Err(error),
        }
    }
}

